#if defined(COMPMATMUL_USE_MKL_FFT)
    FFTTransformer<float> fftf(128);
#elif defined(COMPMATMUL_USE_FFTW_FFT)
    float* scratchf = array::allocate<float>(2*128 + 2);
    FFTTransformer<float> fftf(128, scratchf);
    deallocate(scratchf);
#endif
    complex_t<float>* z_leftf = array::allocate<complex_t<float>>(65);
    complex_t<float>* z_rightf = array::allocate<complex_t<float>>(65);
    
    fftf.fwd(z_leftf, x_leftf);
    fftf.fwd(z_rightf, x_rightf);

    float rel_tolf = 1e-4f;
    float abs_tolf = 1e-5f;

    for (int i = 0; i < 65; ++i) {
        REQUIRE_THAT(z_leftf[i].real, WithinRel(y_leftf[i].real, rel_tolf));
        REQUIRE_THAT(z_leftf[i].imag, WithinRel(y_leftf[i].imag, rel_tolf));
        REQUIRE_THAT(z_rightf[i].real, WithinRel(y_rightf[i].real, rel_tolf));
        REQUIRE_THAT(z_rightf[i].imag, WithinRel(y_rightf[i].imag, rel_tolf));
        REQUIRE_THAT(abs_diff<float>(z_leftf[i], y_leftf[i]), WithinAbs(0.0f, abs_tolf));
    }

    REQUIRE(array::almost_equal(65, z_leftf, y_leftf, abs_tolf));
    REQUIRE(array::almost_equal(65, z_rightf, y_rightf, abs_tolf));

    complex_t<float>* zf = array::allocate<complex_t<float>>(65);

    array::mul(65, zf, z_leftf, z_rightf);

    for (int i = 0; i < 65; ++i) {
        REQUIRE_THAT(zf[i].real, WithinRel(yf[i].real, rel_tolf));
        REQUIRE_THAT(zf[i].imag, WithinRel(yf[i].imag, rel_tolf));
        REQUIRE_THAT(abs_diff<float>(zf[i], yf[i]), WithinAbs(0.0f, abs_tolf));
    }
    REQUIRE(array::almost_equal(65, zf, yf, abs_tolf));
    float* vf = array::allocate<float>(128);

    fftf.inv(vf, zf);

#ifdef COMPMATMUL_USE_FFTW_FFT
    // MKL scales the inverse by 1/n, but FFTW does not
    array::mul(128, vf, 1.0f/128.0f);
#endif // COMPMATMUL_USE_FFTW_FFT

    for (int i = 0; i < 128; ++i) {
        REQUIRE_THAT(vf[i], WithinRel(wf[i], rel_tolf));
    }
    REQUIRE(array::almost_equal(128, vf, wf, abs_tolf));

    deallocate(vf);
    deallocate(zf);
    deallocate(z_leftf);
    deallocate(z_rightf);
    
