    index_t n_left = 23;
    index_t n_inner = 19;
    index_t n_right = 13;

    int d = 1;
    int b = 16384;
    int blog2 = array::ilog2(static_cast<unsigned int>(b));
    float* p = array::allocate<float>(d*b);


    uint64_t* ha_params = array::allocate<uint64_t>(d*MultiplyAddShiftHash::NUM_PARAMS);
    uint64_t* sa_params = array::allocate<uint64_t>(d*MultiplyAddShiftHash::NUM_PARAMS);
    uint64_t* hb_params = array::allocate<uint64_t>(d*MultiplyAddShiftHash::NUM_PARAMS);
    uint64_t* sb_params = array::allocate<uint64_t>(d*MultiplyAddShiftHash::NUM_PARAMS);

    REQUIRE(ha_params != nullptr);
    REQUIRE(sa_params != nullptr);
    REQUIRE(hb_params != nullptr);
    REQUIRE(sb_params != nullptr);
    array::random::RNG_t rng(0xCAFEBABECAFEBABEULL);
    rng.fill(d*MultiplyAddShiftHash::NUM_PARAMS, ha_params);
    rng.fill(d*MultiplyAddShiftHash::NUM_PARAMS, sa_params);
    rng.fill(d*MultiplyAddShiftHash::NUM_PARAMS, hb_params);
    rng.fill(d*MultiplyAddShiftHash::NUM_PARAMS, sb_params);


